	class PlateListingTextField : ListingTextField {

		PlateListingTextField(ProxyObj<object> proxy, PlateFieldTextField field,
				ListingFieldHighlightFactoryAdapter hlFactory) : base(this, proxy, field, hlFactory)
    {
		}

		PlateFieldTextField getPlateTextField() {
			return (PlateFieldTextField) field;
		}
	}

	class PlateFieldTextField : VerticalLayoutTextField {

		private bool isCommentClipped;
		private string commentText;
		private List<FieldElement> textElements;

		PlateFieldTextField(List<FieldElement> textElements, PlateFieldFactory factory,
				ProxyObj<object> proxy, int startX, int width, string commentText,
				bool isCommentClipped, FieldHighlightFactory hlFactory) : base(textElements, startX, width, int.MaxValue, hlFactory)
    {
			this.textElements = textElements;
			this.commentText = commentText;
			this.isCommentClipped = isCommentClipped;
		}

		public PlateCommentRowElement getPlateCommentElement(int viewRow) {

			FieldElement element = textElements.get(viewRow);
			if (!(element is PlateCommentRowElement)) {
				return null; // this row is not a comment row
			}

			return (PlateCommentRowElement) element;
		}

		/* @Override */
		public bool isClipped() {
			return isCommentClipped;
		}

		/* @Override */
		public string getTextWithLineSeparators() {
			// note: this is the comment text which will be blank for default plate comments
			return commentText;
		}

		/* @Override */
		protected List<string> getLines() {
			// open up access for testing
			return base.getLines();
		}

		int getLeadingFillerLineCount() {
			int count = 0;

			foreach (string line in getLines()) {
				count++;
				if (line.isEmpty()) {
					continue; // skip leading blank lines
				}

				if (line.startsWith("*")) {
					break;
				}
			}

			return count;
		}
	}

	/**
	 * A composite element for a row of text inside of the plate comment.
	 */
	private static class PlateCommentRowElement : CompositeFieldElement {

		public PlateCommentRowElement(FieldElement[] elements) : base(elements)
    {
		}

		int getEllipsisEnd() {
			int prefixCol = 0;
			int commentCol = 1;
			FieldElement prefix = getFieldElementByIndex(prefixCol);
			FieldElement comment = getFieldElementByIndex(commentCol);
			return prefix.length() + comment.length() + ELLIPSIS.length();
		}

		string getClippedText() {
			int commentCol = 1;
			FieldElement comment = getFieldElementByIndex(commentCol);
			return comment.getText();
		}

		bool isClipped() {
			// Our structure when constructed of field elements:
			// 		prefix, comment, ellipsis, suffix
			// (where ellipsis will be empty when not clipped)

			int commentCol = 1;
			FieldElement comment = getFieldElementByIndex(commentCol);
			return comment is ClippedPlateRowFieldElement;
		}
	}

	/**
	 * A class that represents clipped comment content.  It has the clipped content and the full
	 * content.
	 */
	private static class ClippedPlateRowFieldElement : WrappedFieldElement {

		private FieldElement fullElement;

		protected ClippedPlateRowFieldElement(FieldElement fullElement, FieldElement @delegate) : base(@delegate)
    {
			this.fullElement = fullElement;
		}

		/* @Override */
		public FieldElement substring(int start, int end) {
			FieldElement newDelegate = base.substring(start, end);
			return new ClippedPlateRowFieldElement(fullElement, newDelegate);
		}

		/* @Override */
		public FieldElement replaceAll(char[] targets, char replacement) {
			FieldElement newDelegate = base.replaceAll(targets, replacement);
			return new ClippedPlateRowFieldElement(fullElement, newDelegate);
		}
	}

	private class FieldElementResult {
		private FieldElement element;
		private bool isClipped;

		FieldElementResult(FieldElement element, bool isClipped) {
			this.element = element;
			this.isClipped = isClipped;
		}

		bool isClipped() {
			return isClipped;
		}

		FieldElement getFieldElement() {
			return element;
		}
	}
}
